import { sqliteTable, text, integer, index } from 'drizzle-orm/sqlite-core';
import { relations, sql } from 'drizzle-orm';
import { user } from '@/db/auth-schema';

/**
 * App-owned tables. Better Auth owns user/session/account/verification —
 * those live in auth-schema.ts and are generated by its CLI.
 */

/** Women's Hack Day is a team competition: exactly 3 participants per team. */
export const MIN_TEAM_SIZE = 3;
export const MAX_TEAM_SIZE = MIN_TEAM_SIZE;

/**
 * Team — created by a captain, up to MAX_TEAM_SIZE members.
 * inviteSlug is a URL-safe slug derived from the team name (e.g. "cool-hackers"),
 * used for /invite/$slug links.
 */
export const team = sqliteTable('team', {
  id: text('id').primaryKey(), // crypto.randomUUID()
  name: text('name').notNull().unique(),
  // Canonicalized name, for case- and spacing-insensitive uniqueness checks.
  nameCanonical: text('name_canonical').notNull().unique(),
  inviteSlug: text('invite_slug').notNull().unique(),
  captainId: text('captain_id')
    .notNull()
    .references(() => user.id, { onDelete: 'cascade' }),
  createdAt: integer('created_at', { mode: 'timestamp_ms' })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .notNull(),
  updatedAt: integer('updated_at', { mode: 'timestamp_ms' })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .notNull(),
});

export type Team = typeof team.$inferSelect;
export type NewTeam = typeof team.$inferInsert;

/**
 * Participant — the profile captured during onboarding (step 2 of registration).
 * teamId is nullable: it is set when the participant creates or joins a team.
 */
export const participant = sqliteTable(
  'participant',
  {
    id: text('id')
      .primaryKey()
      .references(() => user.id, { onDelete: 'cascade' }),
    fullName: text('full_name').notNull(),
    iin: text('iin').notNull(),
    phone: text('phone').notNull(),
    city: text('city').notNull(),
    placeOfStudy: text('place_of_study').notNull(),
    // Required in the UI for school students, optional at the storage layer.
    parentPhone: text('parent_phone'),
    educationLevel: text('education_level').notNull(),
    cvUrl: text('cv_url'),
    attended: integer('attended', { mode: 'boolean' }).default(false).notNull(),
    teamId: text('team_id').references(() => team.id, { onDelete: 'set null' }),
    createdAt: integer('created_at', { mode: 'timestamp_ms' })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer('updated_at', { mode: 'timestamp_ms' })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
  },
  (table) => [index('idx_participant_team_id').on(table.teamId)],
);

export type Participant = typeof participant.$inferSelect;
export type NewParticipant = typeof participant.$inferInsert;

/** Persistent per-user allowance for paid team-name suggestions. */
export const aiGenerationLimit = sqliteTable('ai_generation_limit', {
  userId: text('user_id')
    .primaryKey()
    .references(() => user.id, { onDelete: 'cascade' }),
  nextAllowedAt: integer('next_allowed_at').notNull(),
  windowStartedAt: integer('window_started_at').notNull(),
  requests: integer('requests').notNull(),
});

// ── Relations ────────────────────────────────────────────────────────────────

export const teamRelations = relations(team, ({ many, one }) => ({
  members: many(participant),
  captain: one(participant, { fields: [team.captainId], references: [participant.id] }),
}));

export const participantRelations = relations(participant, ({ one }) => ({
  team: one(team, { fields: [participant.teamId], references: [team.id] }),
  user: one(user, { fields: [participant.id], references: [user.id] }),
}));
